create table if not exists public.members(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,created_at timestamptz not null default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,member_id uuid not null references public.members(id) on delete cascade,month text not null,payment_date date not null,amount numeric(15,2) not null check(amount>0),created_at timestamptz not null default now(),unique(user_id,member_id,month));
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,expense_date date not null,description text not null,amount numeric(15,2) not null check(amount>0),created_at timestamptz not null default now());
create table if not exists public.settings(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,monthly_amount numeric(15,2) not null default 10000 check(monthly_amount>=0),updated_at timestamptz not null default now());
create index if not exists members_user_idx on public.members(user_id);create index if not exists payments_user_month_idx on public.payments(user_id,month);create index if not exists expenses_user_date_idx on public.expenses(user_id,expense_date);
alter table public.members enable row level security;alter table public.payments enable row level security;alter table public.expenses enable row level security;alter table public.settings enable row level security;
drop policy if exists members_select on public.members;create policy members_select on public.members for select to authenticated using(auth.uid()=user_id);drop policy if exists members_insert on public.members;create policy members_insert on public.members for insert to authenticated with check(auth.uid()=user_id);drop policy if exists members_update on public.members;create policy members_update on public.members for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);drop policy if exists members_delete on public.members;create policy members_delete on public.members for delete to authenticated using(auth.uid()=user_id);
drop policy if exists payments_select on public.payments;create policy payments_select on public.payments for select to authenticated using(auth.uid()=user_id);drop policy if exists payments_insert on public.payments;create policy payments_insert on public.payments for insert to authenticated with check(auth.uid()=user_id);drop policy if exists payments_update on public.payments;create policy payments_update on public.payments for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);drop policy if exists payments_delete on public.payments;create policy payments_delete on public.payments for delete to authenticated using(auth.uid()=user_id);
drop policy if exists expenses_select on public.expenses;create policy expenses_select on public.expenses for select to authenticated using(auth.uid()=user_id);drop policy if exists expenses_insert on public.expenses;create policy expenses_insert on public.expenses for insert to authenticated with check(auth.uid()=user_id);drop policy if exists expenses_update on public.expenses;create policy expenses_update on public.expenses for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);drop policy if exists expenses_delete on public.expenses;create policy expenses_delete on public.expenses for delete to authenticated using(auth.uid()=user_id);
drop policy if exists settings_select on public.settings;create policy settings_select on public.settings for select to authenticated using(auth.uid()=user_id);drop policy if exists settings_insert on public.settings;create policy settings_insert on public.settings for insert to authenticated with check(auth.uid()=user_id);drop policy if exists settings_update on public.settings;create policy settings_update on public.settings for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);drop policy if exists settings_delete on public.settings;create policy settings_delete on public.settings for delete to authenticated using(auth.uid()=user_id);
